<script setup lang="ts">
import { onBeforeRouteLeave } from 'vue-router'
import { ApiError } from '~/utils/api-error'
import { createScenarioEditor } from '~/utils/scenario-editor'
const props = defineProps<{ id: string }>(), auth = useAuthStore()
const context = () => ({ scenario: props.id, school: auth.tenant?.school_id ?? '', user: auth.user?.id ?? '', role: auth.tenant?.role ?? '' })
const editor = createScenarioEditor(useScenarioEditorApi(props.id, context().school), context)
const { document: doc, latest, draft, checks, error, busy, uncertain, conflict, checklist, confirmed, pause, dirty, canEdit, block, savedVersion } = editor
const editing = ref(false), signoffOpen = ref(false), inspectorOpen = ref(false), sourceId = ref<string | null>(null), historyVersion = ref('1'), discardOpen = ref(false), leaveOpen = ref(false)
const fieldErrors = computed(() => error.value instanceof ApiError ? error.value.details : [])
let leaveResolve: ((value: boolean) => void) | undefined
function beforeUnload(e: BeforeUnloadEvent) { if (dirty.value || busy.value) { e.preventDefault(); e.returnValue = '' } }
function visibility() { editor.setVisible(!document.hidden) }
function inspect(id: string) { sourceId.value = id; inspectorOpen.value = true }
watch(() => [auth.user?.id, auth.tenant?.school_id, props.id], () => { editing.value = false; signoffOpen.value = false; inspectorOpen.value = false; sourceId.value = null; editor.reset() }, { flush: 'sync' })
watch(() => doc.value?.revision.id, () => { signoffOpen.value = false; historyVersion.value = String(doc.value?.revision.version_number ?? 1) })
watch(confirmed, value => { if (value) signoffOpen.value = false })
onBeforeRouteLeave(() => { if (!dirty.value && !busy.value) return true; leaveOpen.value = true; return new Promise<boolean>(resolve => { leaveResolve = resolve }) })
watch(leaveOpen, value => { if (!value && leaveResolve) { leaveResolve(false); leaveResolve = undefined } })
function leave() { const resolve = leaveResolve; leaveResolve = undefined; leaveOpen.value = false; resolve?.(true) }
function accept() { editing.value = false; editor.acceptLatest(); discardOpen.value = false }
onMounted(() => { window.addEventListener('beforeunload', beforeUnload); document.addEventListener('visibilitychange', visibility); visibility(); void editor.load() })
onBeforeUnmount(() => { window.removeEventListener('beforeunload', beforeUnload); document.removeEventListener('visibilitychange', visibility); leaveResolve?.(false); editor.reset() })
</script>
<template><div class="generation-page editor-workspace"><div class="editor-actions"><NuxtLink :to="`/scenarios/${id}`">← Режим просмотра</NuxtLink><UiButton variant="secondary" :disabled="!!busy" @click="editor.reconcile">Сверить актуальную версию</UiButton></div><UiAlert v-if="error" tone="error"><strong>{{ error.message }}</strong><p v-for="issue in fieldErrors" :key="issue.field+issue.message">{{ issue.field }}: {{ issue.message }}</p></UiAlert><UiAlert v-if="uncertain" tone="warning"><strong>Результат операции неизвестен</strong><p>Повторная отправка заблокирована. Сверьте серверную версию; локальный текст сохранён в этой вкладке.</p><UiButton variant="secondary" :disabled="!!busy" @click="editor.reconcile">Сверить результат</UiButton></UiAlert><UiCard v-if="conflict" class="editor-conflict"><h2>Версия изменилась — сравните изменения</h2><p>Ваш черновик не перезаписан. Автоматического повтора PATCH с новым If-Match нет.</p><UiButton :disabled="!!busy" variant="secondary" @click="editor.reconcile">Перечитать актуальную версию</UiButton><div v-if="latest" class="editor-compare"><div><h3>Ваши изменения</h3><ScenarioJson :value="draft" /></div><div><h3>На сервере · версия {{ latest.revision.version_number }}</h3><ScenarioJson :value="{concept:latest.revision.concept,pedagogical_goal:latest.revision.pedagogical_goal,pedagogical_tasks:latest.revision.content_payload.pedagogical_tasks ?? null,stages:latest.revision.content_payload.stages ?? null,materials:latest.revision.content_payload.materials ?? null}" /></div></div><UiButton v-if="latest" :disabled="!!busy" @click="discardOpen=true">Использовать серверную версию</UiButton></UiCard><UiState v-if="!doc && busy" kind="loading" title="Загружаем редактор" /><UiState v-else-if="!doc" kind="error" title="Редактор недоступен"><UiButton @click="editor.load">Повторить чтение</UiButton></UiState><template v-if="doc"><UiAlert v-if="savedVersion" tone="info">Изменения сохранены: создана ревизия {{ savedVersion }}. Проверка и подтверждение предыдущей версии на неё не переносятся.</UiAlert><UiAlert v-if="confirmed" tone="info">Подтверждение принято сервером для этой ревизии и доказательной базы на момент отправки. Перед использованием учитывайте возможные изменения источников.</UiAlert><ScenarioResult :scenario="doc.scenario" @inspect="inspect"><template #actions><div class="editor-actions"><UiButton v-if="canEdit" variant="secondary" :disabled="!!busy || conflict || !!uncertain" @click="editing=!editing">{{ editing ? 'Свернуть поля' : 'Редактировать сценарий' }}</UiButton><UiButton v-if="canEdit" :disabled="!dirty || !!busy || conflict || !!uncertain" :loading="busy==='save'" @click="editor.save"><img src="/icons/fe007/save.svg" width="17" height="17" alt="">Сохранить новую ревизию</UiButton><UiButton v-if="canEdit" variant="secondary" :disabled="!!busy || dirty || conflict || !!uncertain" @click="signoffOpen=true">Подтверждение педагогом</UiButton><ExportPanel :key="`${auth.user?.id}:${auth.tenant?.school_id}:${doc.revision.id}`" :scenario-id="id" :revision-id="doc.revision.id" :version="doc.revision.version_number" :disabled="dirty || !!busy || conflict || !!uncertain" /><span v-if="dirty" role="status" class="text-warning">Есть несохранённые изменения</span></div><p v-if="!canEdit" class="muted">Выбранная ревизия доступна только для чтения. Изменения требуют текущей версии и школьных полномочий.</p><details class="revision-history"><summary>Ревизии сценария</summary><p>API не предоставляет список всех ревизий. Откройте известную версию по номеру; исторические ревизии доступны только для чтения.</p><div class="editor-actions"><UiField v-model="historyVersion" label="Номер ревизии" type="number" min="1" /><UiButton :disabled="!!busy || dirty || !!uncertain" variant="secondary" @click="editing=false; editor.history(Number(historyVersion))">Открыть ревизию</UiButton><UiButton :disabled="!!busy || dirty || !!uncertain" variant="secondary" @click="editing=false; editor.load()">Текущая ревизия</UiButton></div></details></template><template v-if="editing && draft && canEdit" #purpose><ScenarioEditFields v-model="draft" section="purpose" :disabled="!!busy || conflict || !!uncertain" :errors="fieldErrors" /></template><template v-if="editing && draft && canEdit" #stages><ScenarioEditFields v-model="draft" section="stages" :disabled="!!busy || conflict || !!uncertain" :errors="fieldErrors" /></template><template v-if="editing && draft && canEdit" #materials><ScenarioEditFields v-model="draft" section="materials" :disabled="!!busy || conflict || !!uncertain" :errors="fieldErrors" /></template><template #moderation><RevisionModeration :verification="checks" :busy="!!busy" :disabled="!canEdit || dirty || conflict || !!uncertain" :pause="pause" @verify="editor.verify" @refresh="editor.refreshChecks" /><UiCard v-if="doc.signoff"><h3>Историческое подтверждение</h3><p>{{ doc.signoff.user?.name ?? 'Педагог' }} · {{ doc.signoff.confirmed_at ?? 'Дата не указана' }}</p><p>{{ doc.signoff.teacher_notes }}</p><p>Запись относится к версии {{ doc.revision.version_number }}. GET не сообщает актуальность fingerprint; наличие записи не доказывает действительность допуска после изменения источников.</p></UiCard></template></ScenarioResult></template><UiModal v-model="signoffOpen" title="Подтверждение педагогом"><UiAlert v-if="error" tone="error">{{ error.message }}</UiAlert><TeacherSignoffForm v-model="checklist" :block="block" :warnings="!!checks && (checks.p1>0 || checks.status==='passed_with_warnings')" :busy="!!busy" @confirm="editor.signoff" /></UiModal><UiModal v-model="discardOpen" title="Заменить локальный черновик?"><p>Несохранённые изменения будут удалены из формы. Серверная версия откроется для дальнейшей работы.</p><UiButton variant="secondary" @click="discardOpen=false">Оставить черновик</UiButton><UiButton @click="accept">Использовать серверную версию</UiButton></UiModal><UiModal v-model="leaveOpen" title="Есть несохранённые изменения"><p>При уходе локальный черновик будет утрачен. Уже отправленная операция может завершиться на сервере.</p><UiButton variant="secondary" @click="leaveOpen=false">Остаться</UiButton><UiButton @click="leave">Уйти со страницы</UiButton></UiModal><SourceInspector v-model="inspectorOpen" :source-id="sourceId" /></div></template>
